export function tokenize(s){return s.toLowerCase().match(/[a-z0-9]+/g)||[];}
export function predict(text,m){const words=new Set(tokenize(text));const ids=m.vocab.flatMap((w,i)=>words.has(w)?[i]:[]);if(!ids.length)
return{id:'unknown',score:0};const h=Array.from({length:m.hidden},(_,j)=>Math.tanh(m.b[j]*m.scale+ids.reduce((s,i)=>s+m.w[i*m.hidden+j]*m.scale,0)/Math.sqrt(ids.length)));const logits=m.labels.map((_,i)=>m.ob[i]*m.scale+h.reduce((s,x,j)=>s+x*m.out[j*m.labels.length+i]*m.scale,0));const max=Math.max(...logits);const e=logits.map(x=>Math.exp(x-max));const sum=e.reduce((a,b)=>a+b,0);const sorted=e.map((v,i)=>({id:m.labels[i],score:v/sum})).sort((a,b)=>b.score-a.score);return sorted[0].score>=.7&&sorted[0].score-sorted[1].score>=.25?sorted[0]:{id:'unknown',score:sorted[0].score};}
